package com.example.buddy.ui

enum class GKind { CHOOSE, MISTAKE, ORDER, TYPE }

class GrammarQ(
    val id: String,
    val topic: String,
    val kind: GKind,
    val text: String,
    val answers: List<String>,
    val options: List<String>,
    val wrongIndex: Int,
    val why: String
) {
    fun words(): List<String> = text.split(" ").filter { it.isNotEmpty() }
    fun filled(): String = when (kind) {
        GKind.CHOOSE, GKind.TYPE -> text.replace(Regex("\\s*\\([^)]*\\)"), "").replace("___", answers.first())
        GKind.MISTAKE -> words().mapIndexed { i, w -> if (i == wrongIndex) answers.first() + trailing(w) else w }.joinToString(" ")
        GKind.ORDER -> text
    }

    private fun trailing(w: String): String = w.takeLastWhile { it in ".,!?;:" }
}

class GrammarTopic(
    val id: String,
    val level: String,
    val ru: String, val en: String, val uz: String,
    val ruleRu: String, val ruleEn: String, val ruleUz: String,
    val questions: List<GrammarQ>
)

object GrammarBank {
    fun parse(topic: String, n: Int, line: String): GrammarQ? {
        val f = line.split("|")
        val id = "$topic.$n"
        return when (f.firstOrNull()) {
            "c" -> if (f.size == 5) GrammarQ(id, topic, GKind.CHOOSE, f[1], listOf(f[2]), listOf(f[2]) + f[3].split(";"), -1, f[4]) else null
            "m" -> if (f.size == 5) GrammarQ(id, topic, GKind.MISTAKE, f[1], f[3].split(";"), emptyList(), f[2].toIntOrNull() ?: -1, f[4]) else null
            "o" -> if (f.size == 3) GrammarQ(id, topic, GKind.ORDER, f[1], listOf(f[1]), emptyList(), -1, f[2]) else null
            "t" -> if (f.size == 4) GrammarQ(id, topic, GKind.TYPE, f[1], f[2].split(";"), emptyList(), -1, f[3]) else null
            else -> null
        }
    }

    private fun topic(id: String, level: String, ru: String, en: String, uz: String, ruleRu: String, ruleEn: String, ruleUz: String, vararg lines: String) =
        GrammarTopic(id, level, ru, en, uz, ruleRu, ruleEn, ruleUz, lines.mapIndexedNotNull { i, l -> parse(id, i, l) })

