    fun topic(id: String): GrammarTopic? = topics.firstOrNull { it.id == id }

    fun byId(id: String): GrammarQ? = topic(id.substringBefore('.'))?.questions?.firstOrNull { it.id == id }

    fun all(): List<GrammarQ> = topics.flatMap { it.questions }
}
